from Registry.Registry import Registry

def get_hostname_variations():
    reg = Registry('ctf_files/SYSTEM')
    locations = [
        "ControlSet001\\Control\\ComputerName\\ComputerName",
        "ControlSet001\\Services\\Tcpip\\Parameters",
        "Select\\Current",
        "ControlSet001\\Control\\ComputerName\\ActiveComputerName"
    ]
    results = []
    for loc in locations:
        try:
            key = reg.open(loc)
            for value in key.values():
                if "name" in value.name().lower() or "hostname" in value.name().lower():
                    results.append(f"{loc} - {value.name()}: {value.value()}")
        except Exception as e:
            continue
    return results

print("Possible Hostnames:")
for result in get_hostname_variations():
    print(result)
