def get_system_info():
    reg = Registry('ctf_files/SYSTEM')
    try:
        key = reg.open("ControlSet001\\Services\\Tcpip\\Interfaces")
        print("\nNetwork Interfaces:")
        for interface in key.subkeys():
            try:
                for value in interface.values():
                    if any(x in value.name().lower() for x in ['dhcp', 'ip', 'subnet']):
                        print(f"{interface.name()} - {value.name()}: {value.value()}")
            except:
                continue

        key = reg.open("ControlSet001\\Control\\SystemInformation")
        print("\nSystem Information:")
        for value in key.values():
            print(f"{value.name()}: {value.value()}")
    except Exception as e:
        print(f"Error: {e}")

get_system_info()
